from pathlib import Path

ROOT=Path('.')
p=ROOT/'voyage-v014.js'
s=p.read_text(encoding='utf-8')

old="""function scheduleAI(){clearTimeout(aiTimer);if(!root.hidden&&isAITurn()){const delay=aiDelayOverride||1050;aiDelayOverride=0;aiTimer=setTimeout(aiStep,delay)}}
function aiStep(){const p=current(state),e=state.exp;let a;if(state.overflow)a={type:'discardOwned',id:state.overflow==='crew'?[...p.crew].sort((a,b)=>Object.values(CARDS[a.id].stats).reduce((x,y)=>x+y)-Object.values(CARDS[b.id].stats).reduce((x,y)=>x+y))[0].uid:p.treasures[0]};else if(e){if(e.phase==='ready')a={type:'roll'};else if(e.phase==='dice'){const o=controls(state)[0];a=o?{type:'control',id:o.id,index:e.dice.indexOf(0)>=0?e.dice.indexOf(0):0}:{type:'resolve'}}else if(e.phase==='loss')a=p.crew.some(c=>e.crew.includes(c.uid)&&c.id==='C12')?{type:'loss',prevent:'surgeon'}:e.treasures.includes('T19')?{type:'loss',prevent:'medallion'}:{type:'loss',id:(p.crew.find(c=>e.crew.includes(c.uid)&&c.id==='C10')||p.crew.find(c=>e.crew.includes(c.uid))).uid};else if(e.phase==='treasure')a={type:'keepTreasure',id:e.choices[0]};else a={type:'finish'}}else if(!state.location){const ids=Object.keys(LOCATIONS).filter(l=>legalWorker(state,l)),tired=p.crew.filter(c=>c.exhausted).length,ready=p.crew.length-tired;const normalOrder=p.crew.length<3&&p.gold>=3?['veteran','tavern','black','work','market','dock','quarters','witch']:p.supply<(unlocked(state,4)?9:unlocked(state,3)?6:3)?(p.gold?['market','work','dock','tavern','quarters','black','witch','veteran']:['work','dock','tavern','quarters','market','black','witch','veteran']):['dock','veteran','work','market','tavern','quarters','witch','black'];const order=tired&&(unlocked(state,3)||ready<=1)?['quarters',...normalOrder.filter(x=>x!=='quarters')]:normalOrder;a={type:'worker',location:order.find(l=>ids.includes(l))}}else{const l=state.location;if(l==='work')a={type:'work'};else if(l==='market'&&p.gold)a={type:'market',amount:Math.min(5,p.gold)};else if(['tavern','veteran','black'].includes(l)){if(l==='black'&&!state.blackRefreshed)a=p.gold?{type:'refresh',ids:state.market.slice(0,Math.min(3,p.gold))}:{type:'skip'};else{const id=(l==='veteran'?state.veteranMarket:state.market).find(id=>CARDS[id].cost-(l==='black'?1:0)<=p.gold);a=id?{type:'recruit',id}:{type:l==='black'?'blackSkip':'skip'}}}else if(l==='quarters'){const tired=p.crew.filter(c=>c.exhausted).length;if(tired){aiDelayOverride=2200;a={type:'ready',rested:tired}}else a={type:'skip'}}else if(l==='dock'){const crew=p.crew.filter(c=>!c.exhausted).map(c=>c.uid);const ids=[...Object.values(state.stacks).flat().map(st=>st[0]),state.final[0]].filter(id=>id&&available(state,id));const id=ids.filter(id=>{const c=CARDS[id],e={mission:id,crew,treasures:p.treasures,step:0,blessing:p.blessing};return crew.length&&p.supply>=supplyCost(p,c.zone||4)&&baseScore(p,e)>=testInfo(e).target-((c.zone||4)>=3?4:2)}).sort((a,b)=>(CARDS[b].zone||4)-(CARDS[a].zone||4))[0];if(id){a={type:'launch',mission:id,crew}}}if(!a)a={type:'skip'}}if(a){const rested=a.type==='ready'?a.rested||0:0;const ok=doAct(a);if(!ok)toast('AI action could not complete. Resume the action manually.');else if(rested)toast(`${p.name} rested at Crew Quarters — ${rested} Crew are Ready.`);}}
"""
new="""function scheduleAI(){clearTimeout(aiTimer);if(!root.hidden&&isAITurn()){const delay=aiDelayOverride||1050;aiDelayOverride=0;aiTimer=setTimeout(aiStep,delay)}}
const aiMissionMargin=(p,id,crew,blessing=p.blessing,step=0)=>{const e={mission:id,crew,treasures:p.treasures,step,blessing};return baseScore(p,e)-testInfo(e).target};
const aiMissionViable=(p,id,crew,blessing=p.blessing)=>{const c=CARDS[id],z=c.zone||4,gap=z>=3?4:2;if(!crew.length||p.supply<supplyCost(p,z))return false;if(c.kind==='final')return c.steps.every((_,step)=>aiMissionMargin(p,id,crew,blessing,step)>=-gap);return aiMissionMargin(p,id,crew,blessing,0)>=-gap};
const aiBestFinalBlessing=(p,crew)=>{const id=state.final?.[0];if(!id||!available(state,id)||!crew.length)return null;const choices=['Combat','Sailing','Search'];return choices.map(blessing=>{const margins=CARDS[id].steps.map((_,step)=>aiMissionMargin(p,id,crew,blessing,step));return {blessing,worst:Math.min(...margins),total:margins.reduce((a,b)=>a+b,0)}}).sort((a,b)=>b.worst-a.worst||b.total-a.total)[0]||null};
function aiStep(){const p=current(state),e=state.exp;let a;if(state.overflow)a={type:'discardOwned',id:state.overflow==='crew'?[...p.crew].sort((a,b)=>Object.values(CARDS[a.id].stats).reduce((x,y)=>x+y)-Object.values(CARDS[b.id].stats).reduce((x,y)=>x+y))[0].uid:p.treasures[0]};else if(e){if(e.phase==='ready')a={type:'roll'};else if(e.phase==='dice'){const o=controls(state)[0];a=o?{type:'control',id:o.id,index:e.dice.indexOf(0)>=0?e.dice.indexOf(0):0}:{type:'resolve'}}else if(e.phase==='loss')a=p.crew.some(c=>e.crew.includes(c.uid)&&c.id==='C12')?{type:'loss',prevent:'surgeon'}:e.treasures.includes('T19')?{type:'loss',prevent:'medallion'}:{type:'loss',id:(p.crew.find(c=>e.crew.includes(c.uid)&&c.id==='C10')||p.crew.find(c=>e.crew.includes(c.uid))).uid};else if(e.phase==='treasure')a={type:'keepTreasure',id:e.choices[0]};else a={type:'finish'}}else if(!state.location){const ids=Object.keys(LOCATIONS).filter(l=>legalWorker(state,l)),tired=p.crew.filter(c=>c.exhausted).length,ready=p.crew.length-tired,crew=p.crew.filter(c=>!c.exhausted).map(c=>c.uid),finalBless=aiBestFinalBlessing(p,crew),shouldBless=unlocked(state,4)&&!p.blessing&&p.gold>=3&&ids.includes('witch')&&finalBless&&aiMissionViable(p,state.final[0],crew,finalBless.blessing);const normalOrder=p.crew.length<3&&p.gold>=3?['veteran','tavern','black','work','market','dock','quarters','witch']:p.supply<(unlocked(state,4)?9:unlocked(state,3)?6:3)?(p.gold?['market','work','dock','tavern','quarters','black','witch','veteran']:['work','dock','tavern','quarters','market','black','witch','veteran']):['dock','veteran','work','market','tavern','quarters','witch','black'];const strategicOrder=shouldBless?['witch',...normalOrder.filter(x=>x!=='witch')]:normalOrder;const order=tired&&(unlocked(state,3)||ready<=1)?['quarters',...strategicOrder.filter(x=>x!=='quarters')]:strategicOrder;a={type:'worker',location:order.find(l=>ids.includes(l))}}else{const l=state.location;if(l==='work')a={type:'work'};else if(l==='market'&&p.gold)a={type:'market',amount:Math.min(5,p.gold)};else if(['tavern','veteran','black'].includes(l)){if(l==='black'&&!state.blackRefreshed)a=p.gold?{type:'refresh',ids:state.market.slice(0,Math.min(3,p.gold))}:{type:'skip'};else{const id=(l==='veteran'?state.veteranMarket:state.market).find(id=>CARDS[id].cost-(l==='black'?1:0)<=p.gold);a=id?{type:'recruit',id}:{type:l==='black'?'blackSkip':'skip'}}}else if(l==='quarters'){const tired=p.crew.filter(c=>c.exhausted).length;if(tired){aiDelayOverride=2200;a={type:'ready',rested:tired}}else a={type:'skip'}}else if(l==='witch'){const crew=p.crew.filter(c=>!c.exhausted).map(c=>c.uid),choice=aiBestFinalBlessing(p,crew);a=p.gold>=3&&choice?{type:'bless',id:choice.blessing}:{type:'skip'}}else if(l==='dock'){const crew=p.crew.filter(c=>!c.exhausted).map(c=>c.uid);const ids=[...Object.values(state.stacks).flat().map(st=>st[0]),state.final[0]].filter(id=>id&&available(state,id));const id=ids.filter(id=>aiMissionViable(p,id,crew,p.blessing)).sort((a,b)=>(CARDS[b].zone||4)-(CARDS[a].zone||4))[0];if(id){a={type:'launch',mission:id,crew}}}if(!a)a={type:'skip'}}if(a){const rested=a.type==='ready'?a.rested||0:0;const ok=doAct(a);if(!ok)toast('AI action could not complete. Resume the action manually.');else if(rested)toast(`${p.name} rested at Crew Quarters — ${rested} Crew are Ready.`);}}
"""
if old not in s:
    raise SystemExit('AI block changed; patch target not found')
p.write_text(s.replace(old,new),encoding='utf-8')

# Extend v0.32 AI regression to guard two-step evaluation + strategic blessing.
t=ROOT/'tests/ai-zone3-final-v032.mjs'
r=t.read_text(encoding='utf-8')
old_guard="assert(ui.includes(\"target-((c.zone||4)>=3?4:2)\"),'Zone III/Final should allow up to 4 dice power gap');"
new_guard="assert(ui.includes(\"gap=z>=3?4:2\"),'Zone III/Final should retain the 4-point late-game dice gap');"
if old_guard not in r:
    raise SystemExit('old AI threshold regression guard not found')
r=r.replace(old_guard,new_guard)
marker="assert(!engine.includes(\"c.id==='F3'\"));\n"
extra="""assert(ui.includes('const aiMissionViable='),'AI should centralize mission viability');
assert(ui.includes("c.kind==='final')return c.steps.every"),'Final viability must evaluate every step');
assert(ui.includes('aiMissionMargin(p,id,crew,blessing,step)'),'Final evaluation must score each step separately');
assert(ui.includes('const aiBestFinalBlessing='),'AI should choose a Final blessing strategically');
assert(ui.includes("shouldBless=unlocked(state,4)&&!p.blessing&&p.gold>=3"),'AI should prioritize Sea Witch before a viable Final attempt');
assert(ui.includes("else if(l==='witch')"),'AI must actually resolve the Sea Witch action');
assert(ui.includes("{type:'bless',id:choice.blessing}"),'AI must select and buy its chosen blessing');
"""
if marker not in r:
    raise SystemExit('AI regression marker not found')
t.write_text(r.replace(marker,marker+extra),encoding='utf-8')
